package com.example.domain.model.i18n

internal object DuaMr1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("झोपेतून उठल्यावर", "सर्व स्तुती अल्लाहसाठी आहे, ज्याने आम्हाला मृत्यूनंतर (झोपेनंतर) जीवन दिले, आणि त्याच्याकडेच परत उठून जायचे आहे.", "झोपेतून उठताच अल्लाहचे आभार मानण्यासाठी.", "नबी ﷺ झोपेतून उठल्यावर ही दुआ पठण करत — दिवसाची सुरुवात कृतज्ञता आणि आखिरतच्या आठवणीने."),
        "dua_leaving_home" to DuaText("घरातून बाहेर पडताना", "अल्लाहच्या नावाने; मी अल्लाहवर भरवसा ठेवला. अल्लाहशिवाय कोणतीही शक्ती नाही आणि कोणतेही सामर्थ्य नाही.", "घराबाहेर पाऊल टाकताना अल्लाहच्या संरक्षणासाठी.", "फरिश्ते म्हणतात: 'तुला मार्गदर्शन मिळाले, तुझी काळजी घेतली गेली आणि तुझे रक्षण झाले', आणि शैतान दूर जातो."),
        "dua_anxiety_distress" to DuaText("चिंता व दुःखातून सुटका", "हे अल्लाह! मी चिंता व दुःख, दुर्बलता व आळस, कंजूसपणा व भ्याडपणा, कर्जाचा भार आणि लोकांच्या वर्चस्वापासून तुझा आश्रय मागतो.", "दुःख, चिंता, कर्जाचा भार आणि मानसिक त्रासाच्या वेळी.", "नबी ﷺ ही दुआ वारंवार करत — दुःख, आळस आणि कर्जाच्या चिंतेपासून आश्रय."),
        "dua_sayyidul_istighfar" to DuaText("सय्यिदुल इस्तिगफार", "हे अल्लाह! तूच माझा रब आहेस, तुझ्याशिवाय कोणी उपास्य नाही. तू मला निर्माण केलेस आणि मी तुझा दास आहे, आणि मी माझ्या शक्तीनुसार तुझ्या वचनावर व कराराावर कायम आहे. माझ्या कृत्यांच्या वाईटापासून मी तुझा आश्रय मागतो. माझ्यावरील तुझ्या कृपांची आणि माझ्या पापांची मी कबुली देतो, म्हणून मला क्षमा कर, कारण तुझ्याशिवाय कोणीही पापे माफ करत नाही.", "सकाळ आणि संध्याकाळ — नबी ﷺ यांनी शिकवलेली तौबाची सर्वोत्तम दुआ.", "जो दृढ विश्वासाने संध्याकाळी पठण करतो आणि त्याच रात्री मरण पावतो तो जन्नतमध्ये जाईल; सकाळी पठण करण्याचाही हाच फायदा."),
        "dua_parents" to DuaText("आई-वडिलांसाठी दुआ", "हे माझ्या रब! त्या दोघांवर दया कर, जसे त्यांनी लहानपणी माझे पालनपोषण केले.", "आई-वडिलांसाठी कुरआनी दुआ — बालपणीच्या संगोपनाच्या बदल्यात.", "अल्लाहने स्वतः आई-वडिलांसाठी ही दुआ करण्याचा आदेश दिला."),
        "dua_entering_mosque" to DuaText("मशिदीत प्रवेश", "हे अल्लाह! माझ्यासाठी तुझ्या कृपेचे दरवाजे उघड.", "उजवा पाय ठेवून मशिदीत प्रवेश करताना.", "नबी ﷺ यांनी मशिदीत प्रवेश करताना ही दुआ पठण करण्याची शिकवण दिली."),
        "dua_morning_asbahna" to DuaText("सकाळचा जिक्र", "आम्ही सकाळ केली आणि संपूर्ण राज्यसत्तेनेही अल्लाहसाठी सकाळ केली. सर्व स्तुती अल्लाहसाठी आहे. अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही. राज्य त्याचेच, स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "सकाळी पठण करण्याची मसनून दुआ.", "दिवसाची सुरुवात अल्लाहच्या राज्यसत्तेच्या आणि तौहीदच्या कबुलीने होते."),
        "dua_evening_amsayna" to DuaText("संध्याकाळचा जिक्र", "आम्ही संध्याकाळ केली आणि संपूर्ण राज्यसत्तेनेही अल्लाहसाठी संध्याकाळ केली. सर्व स्तुती अल्लाहसाठी आहे. अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही. राज्य त्याचेच, स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "संध्याकाळी पठण करण्याची मसनून दुआ.", "रात्रीची सुरुवात अल्लाहच्या राज्यसत्तेच्या आणि तौहीदच्या कबुलीने होते."),
        "dua_bismillah_la_yadurru" to DuaText("सर्व हानीपासून संरक्षण", "अल्लाहच्या नावाने, ज्याच्या नावासोबत पृथ्वी व आकाशातील कोणतीही गोष्ट हानी पोहोचवू शकत नाही, आणि तो सर्व ऐकणारा, सर्व जाणणारा आहे.", "सकाळी आणि संध्याकाळी तीन-तीन वेळा.", "जो सकाळ-संध्याकाळ तीन वेळा पठण करतो, त्याला कोणतीही गोष्ट हानी पोहोचवणार नाही."),
        "dua_raditu_billahi" to DuaText("अल्लाहला रब मानून समाधान", "मी अल्लाहला रब म्हणून, इस्लामला दीन म्हणून आणि मुहम्मद ﷺ यांना नबी म्हणून स्वीकारून समाधानी आहे.", "सकाळी आणि संध्याकाळी तीन वेळा.", "कयामतच्या दिवशी त्याला समाधानी करणे अल्लाहवर त्याचा हक्क होतो."),
        "dua_hasbiyallah" to DuaText("हस्बियल्लाह (अल्लाह पुरेसा आहे)", "मला अल्लाह पुरेसा आहे, त्याच्याशिवाय कोणी उपास्य नाही, त्याच्यावरच मी भरवसा ठेवला आणि तो महान अर्शचा रब आहे.", "सकाळी आणि संध्याकाळी सात वेळा.", "कुरआनची आयत; दुनिया व आखिरतच्या चिंतांमध्ये अल्लाह पुरेसा होतो."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुब्हानल्लाहि व बिहम्दिही", "अल्लाह पवित्र आहे आणि सर्व स्तुती त्याचीच आहे.", "दिवसातून शंभर वेळा.", "जो दिवसातून शंभर वेळा म्हणतो त्याची पापे माफ होतात, जरी ती समुद्राच्या फेसाइतकी असली तरी."),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वहदहू", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही. राज्य आणि स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "दिवसातून शंभर वेळा पठण करण्याचे मोठे पुण्य.", "दहा गुलाम मुक्त करण्याचे पुण्य, शंभर पुण्ये, शंभर पापे माफ आणि संध्याकाळपर्यंत शैतानापासून संरक्षण."),
        "dua_leaving_mosque" to DuaText("मशिदीतून बाहेर पडताना", "हे अल्लाह! मी तुझ्याकडे तुझी कृपा मागतो.", "डावा पाय बाहेर टाकून मशिदीतून बाहेर पडताना.", "मशिदीतून बाहेर पडताना अल्लाहची कृपा आणि रोजीची मागणी."),
        "dua_after_adhan" to DuaText("अजाननंतर", "हे अल्लाह! या परिपूर्ण हाकेच्या आणि कायम होणाऱ्या नमाजच्या रब! मुहम्मद ﷺ यांना वसीला आणि श्रेष्ठता दे, आणि त्यांना त्या प्रशंसित स्थानापर्यंत पोहोचव ज्याचे तू त्यांना वचन दिले आहेस.", "अजान पूर्ण झाल्यानंतर.", "जो ही दुआ पठण करतो, त्याच्यासाठी कयामतच्या दिवशी नबी ﷺ यांची शफाअत निश्चित होते."),
        "dua_after_salah_istighfar" to DuaText("फर्ज नमाजनंतर", "मी अल्लाहकडे क्षमा मागतो (३ वेळा). हे अल्लाह! तूच सलाम आहेस आणि तुझ्याकडूनच शांती आहे, तू बरकतवान आहेस हे वैभव आणि सन्मानाच्या मालका.", "सलाम फिरवल्यानंतर लगेच.", "नबी ﷺ प्रत्येक फर्ज नमाजनंतर हे पठण करत."),
        "dua_after_salah_help_dhikr" to DuaText("तुझ्या जिक्रमध्ये मला मदत कर", "हे अल्लाह! तुझा जिक्र, तुझे आभार आणि तुझी उत्तम उपासना करण्यात मला मदत कर.", "प्रत्येक नमाजनंतर — नबी ﷺ यांनी मुआज (र.) यांना उपदेश दिला.", "नबी ﷺ यांचा विशेष उपदेश — उपासनेत सौंदर्य आणि सातत्य."),
        "dua_ayatul_kursi" to DuaText("नमाजनंतर आयतुल कुर्सी", "अल्लाह, त्याच्याशिवाय कोणी उपास्य नाही, तो सदैव जिवंत, सर्वांचा आधार आहे. त्याला डुलकी येत नाही ना झोप. आकाश व पृथ्वीत जे काही आहे ते त्याचेच आहे. त्याच्या परवानगीशिवाय त्याच्याकडे कोण शिफारस करू शकतो? जे त्यांच्या पुढे व मागे आहे ते तो जाणतो, आणि ते त्याच्या ज्ञानातील काहीही आत्मसात करू शकत नाहीत, जितके तो इच्छितो तितकेच. त्याची कुर्सी आकाश व पृथ्वीला व्यापून आहे, आणि त्यांचे रक्षण त्याला थकवत नाही, तो सर्वोच्च, महान आहे.", "प्रत्येक फर्ज नमाजनंतर आणि झोपण्यापूर्वी.", "प्रत्येक फर्ज नमाजनंतर पठण करणाऱ्याला जन्नतमध्ये जाण्यापासून फक्त मृत्यू रोखतो; झोपण्यापूर्वी पठण केल्यास सकाळपर्यंत संरक्षण."),
        "dua_before_sleep" to DuaText("झोपण्यापूर्वी", "हे अल्लाह! तुझ्याच नावाने मी मरतो (झोपतो) आणि जगतो (उठतो).", "अंथरुणावर पडल्यानंतर.", "नबी ﷺ झोपण्यापूर्वी ही दुआ पठण करत."),
        "dua_sleep_tasbeeh" to DuaText("झोपण्यापूर्वी तस्बीह-ए-फातिमी", "अल्लाह पवित्र आहे (३३), सर्व स्तुती अल्लाहसाठी आहे (३३), अल्लाह सर्वात महान आहे (३४).", "झोपण्यापूर्वी — नबी ﷺ यांनी फातिमा व अली (र.) यांना शिकवले.", "नबी ﷺ म्हणाले हे तुमच्यासाठी नोकरापेक्षा उत्तम आहे."),
        "dua_sleep_qina_adhab" to DuaText("शिक्षेपासून संरक्षण", "हे अल्लाह! ज्या दिवशी तू तुझ्या दासांना उठवशील त्या दिवशी मला तुझ्या शिक्षेपासून वाचव.", "उजवा हात गालाखाली ठेवून तीन वेळा.", "झोपेला मृत्यूची आठवण आणि आखिरतची तयारी बनवते."),
        "dua_bad_dream" to DuaText("वाईट स्वप्न पडल्यावर", "मी धिक्कारलेल्या शैतानापासून अल्लाहचा आश्रय मागतो.", "वाईट स्वप्न पडल्यावर: डावीकडे तीन वेळा हलके थुंकावे, मग कूस बदलावी.", "वाईट स्वप्न हानी करणार नाही; कोणाला सांगू नका."),
        "dua_yunus" to DuaText("युनूस (अ.) यांची दुआ", "तुझ्याशिवाय कोणी उपास्य नाही, तू पवित्र आहेस, निश्चितच मीच अन्याय करणाऱ्यांपैकी होतो.", "माशाच्या पोटात युनूस (अ.) यांची दुआ — प्रत्येक संकटात.", "जो मुस्लिम कोणत्याही बाबतीत ही दुआ करतो, अल्लाह त्याची दुआ कबूल करतो."),
        "dua_karb" to DuaText("कठीण संकटाच्या वेळची दुआ", "अल्लाहशिवाय कोणी उपास्य नाही, जो महान, सहनशील आहे. अल्लाहशिवाय कोणी उपास्य नाही, जो महान अर्शचा रब आहे. अल्लाहशिवाय कोणी उपास्य नाही, जो आकाशांचा रब, पृथ्वीचा रब आणि सन्माननीय अर्शचा रब आहे.", "कठीण संकट आणि त्रासाच्या वेळी.", "नबी ﷺ संकटाच्या वेळी ही दुआ पठण करत."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हय्यु या कय्यूम", "हे सदैव जिवंत, हे सर्वांचा आधार! तुझ्या कृपेच्या आधाराने मी मदत मागतो.", "जेव्हा एखादी बाब खूप जड होते.", "एखादी बाब नबी ﷺ यांना चिंतित करत असे तेव्हा ते हे पठण करत."),
        "dua_hasbunallah" to DuaText("हस्बुनल्लाहु व निअमल वकील", "आम्हाला अल्लाह पुरेसा आहे आणि तो उत्तम कार्यसाधक आहे.", "शत्रूच्या भीतीत किंवा मोठ्या धोक्याच्या वेळी.", "इब्राहीम (अ.) यांनी आगीत टाकले जाताना आणि नबी ﷺ यांनी धोक्याच्या वेळी हे म्हटले."),
        "dua_entering_home" to DuaText("घरात प्रवेश", "अल्लाहच्या नावाने.", "घरात प्रवेश करताना अल्लाहचे नाव घ्या आणि सलाम करा.", "घरात प्रवेश करताना आणि जेवताना अल्लाहचा जिक्र केल्यास शैतान म्हणतो: इथे तुमच्यासाठी रात्र काढायला जागा नाही ना जेवण."),
        "dua_travel" to DuaText("प्रवासाची (वाहनाची) दुआ", "पवित्र आहे तो ज्याने हे आमच्या अधीन केले, अन्यथा आम्ही याला ताब्यात ठेवू शकलो नसतो, आणि निश्चितच आम्ही आमच्या रबकडे परत जाणार आहोत.", "वाहनावर बसून तीन वेळा अल्लाहु अकबर म्हटल्यानंतर.", "प्रवासाची मसनून दुआ — संरक्षण आणि बरकतसाठी."),
        "dua_entering_market" to DuaText("बाजारात प्रवेश", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही. राज्य आणि स्तुती त्याचीच. तोच जीवन देतो आणि मृत्यू देतो, आणि तो स्वतः सदैव जिवंत आहे, कधीही मरणार नाही. त्याच्याच हाती भलाई आहे आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "बाजारात प्रवेश करताना.", "हदीसमध्ये याचे मोठे पुण्य सांगितले आहे (लाखो पुण्ये)."),
        "dua_adam_forgiveness" to DuaText("आदम (अ.) यांची दुआ", "हे आमच्या रब! आम्ही स्वतःवर अन्याय केला, आणि जर तू आम्हाला क्षमा केली नाहीस आणि आमच्यावर दया केली नाहीस तर आम्ही निश्चितच नुकसान सोसणाऱ्यांपैकी होऊ.", "आदम आणि हव्वा (अ.) यांची तौबाची दुआ.", "मानवजातीची पहिली तौबा — अल्लाहने ती स्वीकारली."),
        "dua_abu_bakr" to DuaText("अबू बक्र (र.) यांना शिकवलेली दुआ", "हे अल्लाह! मी स्वतःवर खूप अन्याय केला आहे, आणि तुझ्याशिवाय कोणीही पापे माफ करत नाही, म्हणून तुझ्याकडून मला क्षमा कर आणि माझ्यावर दया कर, निश्चितच तू क्षमाशील, दयाळू आहेस.", "नमाजमध्ये (तशह्हुदनंतर) पठणासाठी नबी ﷺ यांनी अबू बक्र सिद्दीक (र.) यांना शिकवली.", "नमाजच्या शेवटी पठण करण्याची मसनून दुआ."),
        "dua_astaghfirullah_atubu" to DuaText("दैनंदिन इस्तिगफार", "मी अल्लाहकडे क्षमा मागतो आणि त्याच्याकडे तौबा करतो.", "नबी ﷺ दिवसातून सत्तरपेक्षा जास्त वेळा इस्तिगफार करत.", "नबी ﷺ म्हणाले: मी दिवसातून सत्तरपेक्षा जास्त वेळा अल्लाहकडे क्षमा मागतो आणि तौबा करतो."),
        "dua_laylatul_qadr" to DuaText("लैलतुल कद्रची दुआ", "हे अल्लाह! तू अत्यंत क्षमाशील आहेस, क्षमा करणे तुला आवडते, म्हणून मला क्षमा कर.", "आयशा (र.) यांना लैलतुल कद्रसाठी शिकवली.", "रमजानच्या शेवटच्या रात्री आणि लैलतुल कद्रची विशेष दुआ."),
        "dua_family_coolness" to DuaText("डोळ्यांचा गारवा (पत्नी-मुले)", "हे आमच्या रब! आमच्या पत्नी आणि संततीकडून आम्हाला डोळ्यांचा गारवा दे, आणि आम्हाला ईशपरायणांचे इमाम बनव.", "सदाचारी पत्नी/पती आणि मुलांसाठी कुरआनी दुआ.", "घरात शांती आणि सदाचारी संततीसाठी."),
        "dua_righteous_children" to DuaText("सदाचारी संततीसाठी", "हे माझ्या रब! तुझ्याकडून मला पवित्र संतती दे, निश्चितच तू दुआ ऐकणारा आहेस.", "जकरिया (अ.) यांची दुआ.", "संतती मागण्यासाठी कुरआनी दुआ."),
        "dua_ibrahim_prayer_family" to DuaText("नमाज कायम करणारे", "हे माझ्या रब! मला आणि माझ्या संततीला नमाज कायम करणारे बनव. हे आमच्या रब! माझी दुआ कबूल कर. हे आमच्या रब! हिशोबाच्या दिवशी मला, माझ्या आई-वडिलांना आणि सर्व मोमिनांना क्षमा कर.", "इब्राहीम (अ.) यांची स्वतःसाठी व संततीसाठी दुआ.", "सामान्यतः नमाजच्या शेवटी पठण केली जाते."),
        "dua_newlywed" to DuaText("नवविवाहितांना शुभेच्छा", "अल्लाह तुमच्यासाठी बरकत देवो, तुमच्यावर बरकत उतरवो आणि तुम्हा दोघांना भलाईत एकत्र ठेवो.", "निकाह करणाऱ्याला शुभेच्छा देताना.", "निकाहच्या मसनून शुभेच्छा."),
        "dua_before_eating" to DuaText("जेवणापूर्वी", "अल्लाहच्या नावाने. (विसरल्यास:) अल्लाहच्या नावाने, याच्या सुरुवातीला आणि शेवटी.", "जेवणापूर्वी. विसरल्यास मध्ये पठण करा.", "बिस्मिल्लाह म्हटल्याने जेवणात शैतान भागीदार होत नाही."),
        "dua_after_eating" to DuaText("जेवणानंतर", "सर्व स्तुती अल्लाहसाठी ज्याने मला हे खाऊ घातले आणि माझ्या कोणत्याही शक्ती व सामर्थ्याशिवाय मला ही रोजी दिली.", "जेवण संपल्यानंतर.", "पठण करणाऱ्याची मागील पापे माफ होतात."),
        "dua_host" to DuaText("यजमानासाठी", "हे अल्लाह! तू त्यांना जी रोजी दिली आहेस त्यात बरकत दे, त्यांना क्षमा कर आणि त्यांच्यावर दया कर.", "कोणाकडे जेवल्यानंतर यजमानासाठी.", "मसनून पद्धतीने यजमानाचे आभार."),
        "dua_breaking_fast" to DuaText("रोजा सोडताना", "तहान गेली, नसा ओल्या झाल्या आणि अल्लाहच्या इच्छेने मोबदला निश्चित झाला.", "इफ्तारच्या वेळी.", "नबी ﷺ इफ्तारच्या वेळी हे म्हणत."),
        "dua_new_clothes" to DuaText("नवीन कपडे घालताना", "हे अल्लाह! सर्व स्तुती तुझ्यासाठी आहे, तूच मला हे घातलेस. मी तुझ्याकडे याचे भले आणि ज्यासाठी हे बनवले त्याचे भले मागतो, आणि याच्या वाईटापासून आणि ज्यासाठी बनवले त्याच्या वाईटापासून तुझा आश्रय मागतो.", "नवीन कपडा घालताना (कपड्याचे नाव घेऊन, जसे सदरा किंवा फेटा).", "नबी ﷺ नवीन कपडा घालताना ही दुआ करत. (रोज कपडे घालण्याची दुआ 'कपडे घालणे' मध्ये आहे.)"),
        "dua_rabbana_atina" to DuaText("दुनिया व आखिरतचे भले", "हे आमच्या रब! आम्हाला दुनियेतही भले दे आणि आखिरतमध्येही भले दे, आणि आम्हाला आगीच्या शिक्षेपासून वाचव.", "नबी ﷺ सर्वाधिक ही दुआ करत.", "दुनिया व आखिरतचे सर्व भले एकत्र करणारी दुआ."),
        "dua_rabbi_zidni_ilma" to DuaText("ज्ञानात वाढ", "हे माझ्या रब! माझ्या ज्ञानात वाढ कर.", "ज्ञानात वाढीसाठी.", "अल्लाहने नबी ﷺ यांना फक्त ज्ञानात वाढीची दुआ करण्याचा आदेश दिला."),
        "dua_musa_sharh_sadr" to DuaText("छाती विस्तारण्याची दुआ (मूसा अ.)", "हे माझ्या रब! माझी छाती विस्तार, माझे काम सोपे कर, आणि माझ्या जिभेची गाठ सोडव जेणेकरून लोक माझे बोलणे समजू शकतील.", "परीक्षा, भाषण किंवा कोणत्याही कठीण कामापूर्वी.", "मूसा (अ.) यांची दुआ — मनःशांती आणि कामात सुलभता."),
        "dua_la_tuzigh" to DuaText("हृदयाची दृढता", "हे आमच्या रब! मार्गदर्शन दिल्यानंतर आमची हृदये वाकडी करू नकोस, आणि आम्हाला तुझ्याकडून कृपा दे, निश्चितच तू अत्यंत दाता आहेस.", "मार्गदर्शनावर दृढ राहण्यासाठी.", "ईमानवर दृढ राहण्याची दुआ."),
        "dua_ya_muqallib" to DuaText("हे हृदये फिरवणाऱ्या", "हे हृदये फिरवणाऱ्या! माझे हृदय तुझ्या दीनवर दृढ ठेव.", "नबी ﷺ अनेकदा ही दुआ करत.", "उम्मे सलमा (र.) यांच्या मते नबी ﷺ यांची सर्वाधिक केलेली दुआ."),
        "dua_la_tuakhidhna" to DuaText("सूरह बकराच्या शेवटच्या आयती", "हे आमच्या रब! आम्ही विसरलो किंवा चूक केली तर आम्हाला पकडू नकोस. हे आमच्या रब! आमच्यावर असा भार टाकू नकोस जसा आमच्या पूर्वीच्या लोकांवर टाकलास. हे आमच्या रब! आमच्यावर तो भार टाकू नकोस ज्याची आम्हाला ताकद नाही. आम्हाला माफ कर, क्षमा कर आणि आमच्यावर दया कर. तूच आमचा स्वामी आहेस, म्हणून काफिर लोकांविरुद्ध आम्हाला मदत कर.", "रात्री झोपण्यापूर्वी — सूरह बकराच्या शेवटच्या दोन आयती.", "जो रात्री सूरह बकराच्या शेवटच्या दोन आयती पठण करतो, त्या त्याला पुरेशा होतात."),
        "dua_visiting_sick" to DuaText("आजाऱ्याची भेट", "मी महान अल्लाहकडे, जो महान अर्शचा रब आहे, प्रार्थना करतो की त्याने तुला बरे करावे.", "आजाऱ्याच्या भेटीत सात वेळा.", "मृत्यूची वेळ आली नसेल तर अल्लाह त्याला बरे करतो."),
        "dua_ruqyah_pain" to DuaText("शारीरिक वेदनेसाठी", "मी अल्लाह आणि त्याच्या सामर्थ्याचा आश्रय मागतो त्या त्रासाच्या वाईटापासून जो मला जाणवतो आणि ज्याची मला भीती आहे.", "वेदनेच्या जागी हात ठेवून तीन वेळा बिस्मिल्लाह, मग सात वेळा ही दुआ.", "नबी ﷺ यांनी उस्मान बिन अबिल आस (र.) यांना वेदनेसाठी शिकवली."),
        "dua_ruqyah_nabawi" to DuaText("आजाऱ्यासाठी नबवी रुक्या", "हे अल्लाह, लोकांच्या रब! त्रास दूर कर, बरे कर, तूच बरे करणारा आहेस, तुझ्या आरोग्याशिवाय कोणतेही आरोग्य नाही, असे आरोग्य दे जे कोणताही आजार शिल्लक ठेवत नाही.", "आजाऱ्यावर हात फिरवून.", "नबी ﷺ आपल्या कुटुंबातील आजाऱ्यांच्या भेटीत हे पठण करत."),
        "dua_kalimat_tammat" to DuaText("परिपूर्ण कलिमांचा आश्रय", "मी अल्लाहच्या परिपूर्ण कलिमांचा आश्रय मागतो त्याने निर्माण केलेल्या प्रत्येक गोष्टीच्या वाईटापासून.", "एखाद्या ठिकाणी मुक्काम करताना किंवा संध्याकाळी.", "जो एखाद्या ठिकाणी उतरून हे पठण करतो, तेथून जाईपर्यंत त्याला काहीही हानी करणार नाही."),
        "dua_evil_eye" to DuaText("मुलांचे संरक्षण (दृष्ट)", "मी तुम्हा दोघांना अल्लाहच्या परिपूर्ण कलिमांच्या आश्रयात देतो प्रत्येक शैतान व विषारी प्राण्यापासून, आणि प्रत्येक हानिकारक दृष्टीपासून.", "नबी ﷺ हसन आणि हुसैन (र.) यांच्यावर हे फुंकत.", "मुलांना दृष्ट आणि वाईटापासून वाचवण्याची मसनून दुआ (एका मुलासाठी 'उईजुका')."),
        "dua_seeing_afflicted" to DuaText("कोणाला संकटात पाहिल्यावर", "सर्व स्तुती अल्लाहसाठी ज्याने मला त्या संकटापासून सुरक्षित ठेवले ज्यात तुला टाकले, आणि मला त्याच्या अनेक निर्मितीवर श्रेष्ठता दिली.", "कोणाला संकटात पाहिल्यावर (मनात पठण करा).", "पठण करणारा त्या संकटापासून सुरक्षित राहतो."),
        "dua_istikhara" to DuaText("सलातुल इस्तिखारा", "हे अल्लाह! मी तुझ्या ज्ञानाद्वारे तुझ्याकडे भले मागतो, तुझ्या सामर्थ्याद्वारे शक्ती मागतो, आणि तुझ्या महान कृपेची याचना करतो. तू समर्थ आहेस मी नाही, तू जाणतोस मी नाही, आणि तू अदृश्याचा पूर्ण जाणकार आहेस. हे अल्लाह! जर तुझ्या ज्ञानात हे काम (आपले काम मनात आणा) माझ्या दीन, जीवन आणि परिणामासाठी चांगले असेल तर ते माझ्यासाठी निश्चित कर, सोपे कर आणि त्यात बरकत दे. आणि जर तुझ्या ज्ञानात हे काम माझ्या दीन, जीवन आणि परिणामासाठी वाईट असेल तर ते माझ्यापासून आणि मला त्यापासून दूर कर, आणि जिथे भले असेल ते माझ्यासाठी निश्चित कर, मग मला त्यावर समाधानी कर.", "एखाद्या वैध कामात भले मागण्यासाठी दोन रकअत नफ्ल नंतर.", "नबी ﷺ सहाबांना प्रत्येक कामात इस्तिखारा कुरआनच्या सूरहप्रमाणे शिकवत."),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बिका असबहना", "हे अल्लाह! तुझ्याच मदतीने आम्ही सकाळ केली आणि तुझ्याच मदतीने संध्याकाळ केली, तुझ्याच आदेशाने जगतो व मरतो, आणि तुझ्याकडेच पुनरुत्थान आहे.", "सकाळी.", "नबी ﷺ सहाबांना सकाळ-संध्याकाळ हे शिकवत."),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बिका अमसैना", "हे अल्लाह! तुझ्याच मदतीने आम्ही संध्याकाळ केली आणि तुझ्याच मदतीने सकाळ केली, तुझ्याच आदेशाने जगतो व मरतो, आणि तुझ्याकडेच परत जायचे आहे.", "संध्याकाळी.", "नबी ﷺ सहाबांना सकाळ-संध्याकाळ हे शिकवत."),
        "dua_afiyah_morning" to DuaText("आफियतची दुआ", "हे अल्लाह! मी तुझ्याकडे दुनिया व आखिरतमध्ये क्षमा आणि सुरक्षितता मागतो.", "नबी ﷺ सकाळ-संध्याकाळ ही दुआ कधीही सोडत नसत.", "सुरक्षिततेपेक्षा उत्तम काहीही कोणाला दिले गेले नाही."),
        "dua_afini_fi_badani" to DuaText("शरीर, श्रवण व दृष्टीचे आरोग्य", "हे अल्लाह! माझ्या शरीराला आरोग्य दे, माझ्या श्रवणशक्तीला आरोग्य दे, माझ्या दृष्टीला आरोग्य दे. तुझ्याशिवाय कोणी उपास्य नाही.", "सकाळी आणि संध्याकाळी तीन-तीन वेळा.", "आरोग्य आणि इंद्रियांच्या संरक्षणाची दुआ."),
        "dua_ya_hayyu_aslih" to DuaText("माझी सर्व कामे सुधार", "हे सदैव जिवंत, हे आधार! तुझ्या कृपेने मदत मागतो, माझी सर्व कामे सुधार आणि मला डोळ्याच्या पापणीइतकाही माझ्या मनाच्या हवाली करू नकोस.", "नबी ﷺ यांनी फातिमा (र.) यांना सकाळ-संध्याकाळ पठणाचा उपदेश दिला.", "प्रत्येक कामात अल्लाहची मदत मागणे."),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवैरिया (र.) यांची तस्बीह", "अल्लाह पवित्र आहे आणि स्तुती त्याचीच — त्याच्या निर्मितीच्या संख्येइतकी, त्याच्या प्रसन्नतेनुसार, त्याच्या अर्शच्या वजनाइतकी आणि त्याच्या कलिमांच्या शाईइतकी.", "सकाळी तीन वेळा — तासन्तास जिक्रपेक्षा जड.", "हे चार वाक्य तीन वेळा म्हणणे सकाळपासून दुपारपर्यंतच्या जिक्रपेक्षा वजनाने जड आहे."),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहीमी", "हे अल्लाह! मुहम्मद ﷺ आणि मुहम्मदांच्या कुटुंबावर कृपा उतरव जशी तू इब्राहीम (अ.) आणि इब्राहीमांच्या कुटुंबावर उतरवलीस, निश्चितच तू प्रशंसनीय, गौरवशाली आहेस. हे अल्लाह! मुहम्मद ﷺ आणि मुहम्मदांच्या कुटुंबावर बरकत उतरव जशी तू इब्राहीम (अ.) आणि इब्राहीमांच्या कुटुंबावर उतरवलीस, निश्चितच तू प्रशंसनीय, गौरवशाली आहेस.", "नमाजमध्ये आणि प्रत्येक वेळी नबी ﷺ यांच्यावर दुरूद.", "जो एकदा दुरूद पाठवतो, अल्लाह त्याच्यावर दहा कृपा उतरवतो (मुस्लिम ४०८)."),
        "dua_wudu_after" to DuaText("वुजूनंतर", "मी साक्ष देतो की अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, आणि मुहम्मद ﷺ त्याचे दास आणि रसूल आहेत. हे अल्लाह! मला तौबा करणाऱ्यांमध्ये आणि पवित्र राहणाऱ्यांमध्ये सामील कर.", "वुजू पूर्ण केल्यानंतर.", "जन्नतचे आठही दरवाजे उघडले जातात, ज्यातून इच्छा असेल त्यातून प्रवेश करावा."),
        "dua_wudu_before" to DuaText("वुजूपूर्वी", "अल्लाहच्या नावाने.", "वुजू सुरू करताना.", "ज्याने वुजूवर अल्लाहचे नाव घेतले नाही त्याचे वुजू (पूर्ण) नाही."),
        "dua_istiftah" to DuaText("सना (नमाजची प्रारंभिक दुआ)", "हे अल्लाह! तू पवित्र आहेस तुझ्या स्तुतीसह, तुझे नाव बरकतवान आहे, तुझी प्रतिष्ठा उच्च आहे आणि तुझ्याशिवाय कोणी उपास्य नाही.", "नमाज सुरू करताना, तकबीर-ए-तहरीमानंतर लगेच.", "नमाजची मसनून प्रारंभिक दुआ."),
        "dua_ruku" to DuaText("रुकूमध्ये", "माझा महान रब पवित्र आहे.", "रुकूमध्ये किमान तीन वेळा.", "रुकूची मसनून तस्बीह."),
        "dua_sujood" to DuaText("सजद्यात", "माझा सर्वोच्च रब पवित्र आहे.", "सजद्यात किमान तीन वेळा.", "दास सजद्यात आपल्या रबच्या सर्वात जवळ असतो (मुस्लिम ४८२)."),
        "dua_rising_ruku" to DuaText("रुकूतून उठताना", "जो अल्लाहची स्तुती करतो त्याचे अल्लाहने ऐकले. हे आमच्या रब! सर्व स्तुती तुझ्यासाठीच आहे.", "रुकूतून उठताना आणि सरळ उभे राहून.", "ज्याचे 'रब्बना व लकल हम्द' फरिश्त्यांशी जुळले त्याची मागील पापे माफ."),
        "dua_between_sajdas" to DuaText("दोन सजद्यांच्या मध्ये", "हे माझ्या रब! मला क्षमा कर, हे माझ्या रब! मला क्षमा कर.", "दोन सजद्यांच्या मध्ये बसलेले असताना.", "जलस्याची मसनून दुआ."),
        "dua_before_salam_four" to DuaText("चार गोष्टींपासून आश्रय (सलामपूर्वी)", "हे अल्लाह! मी तुझा आश्रय मागतो जहन्नमच्या शिक्षेपासून, कबरीच्या शिक्षेपासून, जीवन-मृत्यूच्या फितन्यापासून आणि मसीह दज्जालच्या फितन्याच्या वाईटापासून.", "शेवटच्या तशह्हुद आणि दुरूदनंतर, सलामपूर्वी.", "नबी ﷺ यांनी या चार गोष्टींपासून आश्रय मागण्याचा आदेश दिला."),
        "dua_qunoot_witr" to DuaText("वित्रमध्ये कुनूत", "हे अल्लाह! ज्यांना तू मार्गदर्शन दिलेस त्यांच्यात मला मार्गदर्शन दे, ज्यांना सुरक्षितता दिलीस त्यांच्यात मला सुरक्षितता दे, ज्यांचे पालकत्व घेतलेस त्यांच्यात माझे पालकत्व घे, जे दिलेस त्यात बरकत दे, आणि ज्याचा निर्णय केलास त्याच्या वाईटापासून वाचव. निश्चितच तू निर्णय करतोस आणि तुझ्याविरुद्ध निर्णय होत नाही, आणि ज्याचा तू मित्र आहेस तो अपमानित होत नाही. हे आमच्या रब! तू बरकतवान आणि उच्च आहेस.", "वित्र नमाजमध्ये — नबी ﷺ यांनी हसन बिन अली (र.) यांना शिकवली.", "वित्रची मसनून कुनूत. (हनफींमध्ये 'अल्लाहुम्मा इन्ना नस्तईनुका' देखील प्रसिद्ध आहे.)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नस्तईनुका)", "हे अल्लाह! आम्ही तुझ्याकडे मदत आणि क्षमा मागतो, तुझ्यावर ईमान आणतो आणि भरवसा ठेवतो, तुझी उत्तम स्तुती करतो, तुझे आभार मानतो, कृतघ्न होत नाही, आणि जो तुझी अवज्ञा करतो त्याला सोडतो. हे अल्लाह! आम्ही तुझीच उपासना करतो, तुझ्यासाठीच नमाज पढतो आणि सजदा करतो, तुझ्याकडेच धावतो, तुझ्या कृपेची आशा करतो आणि तुझ्या शिक्षेला भितो; निश्चितच तुझी शिक्षा काफिरांना पोहोचणारी आहे.", "वित्रमध्ये — हनफींची प्रथा.", "उमर (र.) यांच्याकडून कुनूतमध्ये वर्णित."),
        "dua_sleep_aslamtu" to DuaText("झोपण्यापूर्वीचे शेवटचे शब्द", "हे अल्लाह! मी स्वतःला तुझ्याकडे सोपवले, माझे काम तुझ्या हवाली केले, माझी पाठ तुझ्या आश्रयात दिली, तुझ्या ओढीने आणि तुझ्या भीतीने. तुझ्यापासून वाचण्याचा आश्रय आणि सुटका नाही तुझ्याकडेच सोडून. मी तू उतरवलेल्या ग्रंथावर आणि तू पाठवलेल्या नबीवर ईमान आणले.", "वुजू करून उजव्या कुशीवर झोपून — सर्वात शेवटचे शब्द.", "त्याच रात्री मृत्यू आल्यास फितरतवर (इस्लामवर) मृत्यू होईल."),
        "dua_waking_night" to DuaText("रात्री जाग आल्यावर", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, राज्य आणि स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे. सर्व स्तुती अल्लाहसाठी, अल्लाह पवित्र आहे, अल्लाहशिवाय कोणी उपास्य नाही, अल्लाह सर्वात महान आहे, आणि अल्लाहशिवाय कोणतीही शक्ती व सामर्थ्य नाही. हे अल्लाह! मला क्षमा कर.", "रात्री जाग आल्यावर.", "दुआ कबूल होते, आणि वुजू करून नमाज पढल्यास नमाज कबूल होते."),
        "dua_hamm_ibn_masud" to DuaText("दुःखाची दुआ (इब्न मसऊद)", "हे अल्लाह! मी तुझा दास आहे, तुझ्या दासाचा मुलगा, तुझ्या दासीचा मुलगा. माझे कपाळ तुझ्या हाती आहे, माझ्यावर तुझा आदेश चालतो, माझ्याबाबत तुझा निर्णय न्याय्य आहे. मी तुझ्याकडे तुझ्या प्रत्येक त्या नावाच्या आधाराने याचना करतो जे तू स्वतःसाठी ठेवलेस, किंवा तुझ्या ग्रंथात उतरवलेस, किंवा तुझ्या कोणत्याही निर्मितीला शिकवलेस, किंवा तुझ्याकडे अदृश्य ज्ञानात राखून ठेवलेस — की कुरआनला माझ्या हृदयाचा वसंत, माझ्या छातीचा प्रकाश, माझ्या दुःखाचा उपाय आणि माझी चिंता दूर करणारा बनव.", "दुःख आणि चिंतेत — अल्लाह दुःखाचे आनंदात रूपांतर करतो.", "अल्लाह त्याची चिंता आणि दुःख दूर करून आनंद देतो."),
        "dua_difficulty_sahl" to DuaText("जेव्हा काम कठीण असते", "हे अल्लाह! काहीही सोपे नाही जोपर्यंत तू ते सोपे करत नाहीस, आणि तू इच्छिल्यास कठीणाला सोपे करतोस.", "एखादे काम कठीण वाटल्यास.", "परीक्षा आणि कठीण कामांत सुलभता."),
        "dua_musibah" to DuaText("संकटावर (इस्तिरजा)", "आम्ही अल्लाहचेच आहोत आणि त्याच्याकडेच परत जाणार आहोत. हे अल्लाह! माझ्या संकटात मला मोबदला दे आणि याहून उत्तम पर्याय दे.", "कोणत्याही नुकसानीवर किंवा संकटावर.", "अल्लाह निश्चितच उत्तम पर्याय देतो — उम्मे सलमा (र.) यांना नबी ﷺ मिळाले."),
        "dua_debt" to DuaText("कर्जमुक्तीसाठी", "हे अल्लाह! तुझ्या हलालद्वारे मला हरामपासून वाचवून पुरेसा हो, आणि तुझ्या कृपेने मला तुझ्याशिवाय सर्वांपासून निरपेक्ष कर.", "कर्जफेडीसाठी — अली (र.) यांनी शिकवली.", "डोंगराएवढे कर्ज असले तरी अल्लाह ते फेडून देतो."),
        "dua_anger" to DuaText("रागाच्या वेळी", "मी धिक्कारलेल्या शैतानापासून अल्लाहचा आश्रय मागतो.", "राग आल्यावर.", "नबी ﷺ म्हणाले: जर त्याने हे म्हटले तर त्याचा राग निघून जाईल."),
        "dua_waswasa" to DuaText("ईमानमधील वसवशाविरुद्ध", "मी अल्लाह आणि त्याच्या रसूलांवर ईमान आणले.", "ईमानबद्दल शैतानी वसवसे आल्यास.", "वसवसा आल्यास हे म्हणावे आणि थांबावे (अऊजु बिल्लाहही पठण करावे)."),
        "dua_travel_full" to DuaText("प्रवासाची संपूर्ण दुआ", "हे अल्लाह! आम्ही या प्रवासात तुझ्याकडे पुण्य आणि तक्वा मागतो आणि असे कर्म जे तुला आवडेल. हे अल्लाह! आमचा हा प्रवास आमच्यासाठी सोपा कर आणि त्याचे अंतर कमी कर. हे अल्लाह! तूच प्रवासातील सोबती आणि कुटुंबाचा रक्षक आहेस.", "प्रवासाला निघताना, 'सुब्हानल्लजी सख्खरा' नंतर.", "प्रवासाची संपूर्ण मसनून दुआ."),
        "dua_return_travel" to DuaText("प्रवासातून परतताना", "आम्ही परतणारे, तौबा करणारे, उपासना करणारे आणि आमच्या रबची स्तुती करणारे आहोत.", "प्रवासातून परतताना.", "नबी ﷺ प्रवासातून परतताना हे म्हणत."),
        "dua_farewell_traveller" to DuaText("प्रवाशाला निरोप", "मी तुझा दीन, तुझी अमानत आणि तुझ्या कर्मांचा परिणाम अल्लाहच्या स्वाधीन करतो.", "प्रवाशाला निरोप देताना.", "अल्लाहच्या स्वाधीन केलेली गोष्ट वाया जात नाही."),
        "dua_entering_town" to DuaText("एखाद्या ठिकाणी मुक्काम", "मी अल्लाहच्या परिपूर्ण कलिमांचा आश्रय मागतो त्याच्या सर्व निर्मितीच्या वाईटापासून.", "एखाद्या ठिकाणी मुक्काम किंवा नवीन शहरात पोहोचल्यावर.", "तेथून निघेपर्यंत काहीही हानी करणार नाही."),
        "dua_boarding_ship" to DuaText("जहाज/वाहनात बसताना", "अल्लाहच्याच नावाने याचे चालणे आणि थांबणे आहे, निश्चितच माझा रब क्षमाशील, दयाळू आहे.", "जहाज किंवा वाहनात बसताना — नूह (अ.) यांचे वचन.", "कुरआनी आयत — नूह (अ.) यांच्या जहाजाची दुआ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("हय्युल कय्यूमसह इस्तिगफार", "मी त्या अल्लाहकडे क्षमा मागतो ज्याच्याशिवाय कोणी उपास्य नाही, जो सदैव जिवंत आणि आधार आहे, आणि त्याच्याकडे तौबा करतो.", "तौबासाठी.", "पापे माफ होतात, जरी तो रणांगणातून पळाला असला तरी."),
        "dua_rabbighfir_warham" to DuaText("रब्बिगफिर वरहम", "हे माझ्या रब! क्षमा कर आणि दया कर, आणि तू सर्वोत्तम दया करणारा आहेस.", "कुरआनी दुआ — क्षमा आणि कृपा.", "सूरह मोमिनूनची शेवटची आयत."),
        "dua_majlis_kaffarah" to DuaText("सभेचे प्रायश्चित्त", "हे अल्लाह! तू पवित्र आहेस तुझ्या स्तुतीसह. मी साक्ष देतो की तुझ्याशिवाय कोणी उपास्य नाही. मी तुझ्याकडे क्षमा मागतो आणि तुझ्याकडे तौबा करतो.", "सभा/बैठकीतून उठताना.", "सभेत झालेल्या चुकीच्या बोलण्याचे प्रायश्चित्त होते."),
        "dua_jami_forgiveness" to DuaText("व्यापक क्षमा", "हे अल्लाह! माझी चूक, माझे अज्ञान, माझ्या कामातील अतिरेक आणि जे तू माझ्यापेक्षा जास्त जाणतोस ते सर्व माफ कर.", "नबी ﷺ यांची व्यापक दुआ.", "नबी ﷺ ही दुआ करत."),
        "dua_parents_nuh" to DuaText("आई-वडिलांसाठी नूह (अ.) यांची दुआ", "हे माझ्या रब! मला, माझ्या आई-वडिलांना, जो ईमानसह माझ्या घरात प्रवेश करतो त्याला, आणि सर्व मोमिन स्त्री-पुरुषांना क्षमा कर.", "आई-वडील आणि मोमिनांसाठी.", "नूह (अ.) यांची दुआ."),
        "dua_shukr_parents" to DuaText("आई-वडिलांच्या कृपेचे आभार आणि सदाचारी संतती", "हे माझ्या रब! मला सामर्थ्य दे की मी तुझ्या त्या कृपेचे आभार मानू जी तू माझ्यावर आणि माझ्या आई-वडिलांवर केलीस, आणि असे सत्कर्म करू जे तुला आवडेल, आणि माझ्या संततीलाही सदाचारी बनव. मी तुझ्याकडे तौबा करतो आणि मी आज्ञाधारकांपैकी आहे.", "चाळीस वर्षांच्या वयाची कुरआनी दुआ.", "कृतज्ञता, सत्कर्म आणि संततीचे सुधारणे — सर्व एका दुआत."),
        "dua_intimacy" to DuaText("वैवाहिक संबंधापूर्वी", "अल्लाहच्या नावाने. हे अल्लाह! आम्हाला शैतानापासून दूर ठेव आणि तू आम्हाला जे (संतती) देशील त्यालाही शैतानापासून दूर ठेव.", "पती-पत्नीच्या संबंधापूर्वी.", "संतती निश्चित असल्यास शैतान तिला कधीही हानी करणार नाही."),
        "dua_ibrahim_children_protection" to DuaText("घर आणि मुलांचे संरक्षण", "हे माझ्या रब! या शहराला सुरक्षित कर आणि मला व माझ्या मुलांना मूर्तिपूजेपासून दूर ठेव.", "इब्राहीम (अ.) यांची दुआ — शहर आणि मुलांचे संरक्षण.", "तौहीदवर कायम राहण्याची दुआ."),
        "dua_drinking_milk" to DuaText("दूध पिताना", "हे अल्लाह! आमच्यासाठी यात बरकत दे आणि आम्हाला आणखी दे.", "दूध पिताना.", "दूध अन्न आणि पेय दोन्हींसाठी पुरेसे असते."),
        "dua_iftar_host" to DuaText("कोणाकडे इफ्तार केल्यावर", "तुमच्याकडे रोजेदार इफ्तार करोत, सदाचारी लोक तुमचे जेवण खावोत आणि फरिश्ते तुमच्यासाठी दुआ करोत.", "कोणाकडे इफ्तार केल्यावर.", "यजमानासाठी नबी ﷺ यांची दुआ."),
        "dua_seeing_first_fruit" to DuaText("हंगामाचे पहिले फळ पाहून", "हे अल्लाह! आमच्या फळांत, आमच्या शहरात, आमच्या साअ आणि मुद्द (मापात) बरकत दे.", "हंगामाचे पहिले फळ पाहून.", "रोजी आणि शहरात बरकतीची दुआ."),
        "dua_good_news" to DuaText("शुभवार्ता मिळाल्यावर", "सर्व स्तुती त्या अल्लाहसाठी ज्याच्या कृपेने चांगली कामे पूर्ण होतात.", "आनंदाची बातमी मिळाल्यावर (आणि सजदा-ए-शुक्र).", "नबी ﷺ आवडती गोष्ट पाहिल्यावर हे म्हणत."),
        "dua_looking_mirror" to DuaText("आरशात पाहताना", "हे अल्लाह! जसे तू माझे रूप सुंदर केलेस, तसेच माझे चारित्र्यही सुंदर कर.", "आरशात पाहताना.", "नबी ﷺ ही दुआ करत (आरशाच्या अटीशिवायही सिद्ध आहे)."),
        "dua_rabbana_taqabbal" to DuaText("कर्मांची स्वीकृती", "हे आमच्या रब! आमच्याकडून स्वीकार कर, निश्चितच तू ऐकणारा, जाणणारा आहेस. आणि आमची तौबा स्वीकार कर, निश्चितच तू तौबा स्वीकारणारा, दयाळू आहेस.", "इब्राहीम आणि इस्माईल (अ.) यांनी काबा बांधताना मागितली.", "प्रत्येक सत्कर्मानंतर स्वीकृतीची दुआ."),
    )
}
